export const locales = ["zh", "en", "ar"];

export const localeLabels = {
  zh: "中文",
  en: "English",
  ar: "العربية",
};

export function normalizeLocale(value) {
  return locales.includes(value) ? value : "zh";
}

export function dirForLocale(locale) {
  return locale === "ar" ? "rtl" : "ltr";
}

export async function getLocale() {
  try {
    const { cookies } = await import("next/headers");
    const store = await cookies();
    return normalizeLocale(store.get("lily_locale")?.value);
  } catch {
    return "zh";
  }
}

export async function getI18n() {
  const locale = await getLocale();
  return { locale, dir: dirForLocale(locale), t: dictionaries[locale] };
}

